(async()=>{const out={};for(const rate of [-1,-.5,-1.5])for(const offset of [0,4]){const c=new OfflineAudioContext(1,12,8000),s=c.createBufferSource(),b=c.createBuffer(1,5,8000);b.getChannelData(0).set([10,20,5,40,50]);s.buffer=b;s.playbackRate.value=rate;s.connect(c.destination);s.start(0,offset/8000);out[rate+':'+offset]=Array.from((await c.startRendering()).getChannelData(0))}return out})()
